import {configureCardSkins} from '/card-skins.js';
import {animatedCharacter} from '/character-motion.js';
import {equityInputs,winningSelection,showdownHighlights} from '/poker-insights.js';
import {circularSeats as portraitSeats,turnFraction,seatMetrics} from '/table-layout.js';
import {diffTableEffects,displayedPot} from '/effects.js';
import {CHARACTERS,characterById,DEFAULT_CHARACTER} from '/characters.js';
import {raiseLadder,raisePresets,nearestStop,stepStop} from '/raise-ladder.js';
import {MOODS,MOOD_LINGER_MS,moodIcon} from '/reactions.js';
import {createCardPeek} from '/card-peek.js';
const $=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Number(n||0).toLocaleString('vi-VN');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
let sessions={},profile=read('bella.profile',''),room=null,session=null,page='home',busy=false,polling=false,storage='loading',online=true,lastErrorAt=0,peek=false,clockOffset=0;
const urlCode=new URL(location.href).searchParams.get('room')?.toUpperCase()||'';
let account=null,authReady=false,authMode='login',authBusy=false,lastWalletTour=null,accountGeneration=0;
let selectedCharacter=DEFAULT_CHARACTER;
let unlockedCharacters=[];
const isCharacterLocked=id=>!account?.ownedSkins.includes(id);

const lastCode=read('bella.last','');
let raiseDraft={key:null,value:null};
const tableEffects=new Map();
let winningCards=null,equityKey=null,equityResult=null,equityWorker=null,equityBroken=false;
let raiseOpen=false,raiseOpenKey=null,gamePanel=null;
const save=()=>{if(account)localStorage.setItem('bella.sessions.'+account.id,JSON.stringify(sessions));};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
async function request(body,code=session?.code,token=session?.token){
 const generation=accountGeneration;
 const response=await fetch(body?'/api':`/api?code=${encodeURIComponent(code||'health')}`,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:`Bearer ${token}`}:{})},body:body?JSON.stringify({...body,requestId:body.requestId||crypto.randomUUID()}):undefined,credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(12000)});
 let data;try{data=await response.json();}catch{throw new Error('Không kết nối được máy chủ.');}if(code!=='health'&&generation!==accountGeneration)throw new Error('Phiên tài khoản đã thay đổi.');if(!response.ok)throw new Error(data.error||'Không thực hiện được yêu cầu.');return data;
}
function applyAccount(value){if(account?.id===value.id&&(value.version||0)<(account.version||0))return;const changed=account?.id!==value.id;account=value;if(document.documentElement)document.documentElement.dataset.cardSkin=value.equippedCardSkin||'classic';selectedCharacter=value.equippedSkin;unlockedCharacters=value.ownedSkins;profile=value.username;if(changed){accountGeneration++;sessions=read('bella.sessions.'+value.id,{});session=null;room=null;page='home';}}
async function refreshWallet(){const data=await request(null,'account',null);applyAccount(data.account);render();}
function accept(data){if(data.account)applyAccount(data.account);if(data.token){session={code:data.room.code,token:data.token};sessions[session.code]=session;save();}const previous=room?.version;queueTableEffects(room,data.room);room=data.room;clockOffset=room.serverNow-Date.now();online=true;if(previous!==room.version||page==='home')render();updateClocks();syncPeek();const reward=room.coinReward,key=room.code+':'+room.hand?.id;if(reward?.amount&&room.players.find(p=>p.id===reward.playerId)?.accountId===account?.id&&lastWalletTour!==key){lastWalletTour=key;refreshWallet().then(()=>toast('Thắng tour với bot: +1 coin!')).catch(()=>{});}}

async function send(body){if(busy)return;busy=true;render();try{const data=await request({...body,code:session.code});accept(data);}catch(e){toast(e.message);}finally{busy=false;render();}}

function characterImage(id,cls='character-avatar'){return animatedCharacter(characterById(id),cls);}
function characterSummary(){const c=characterById(selectedCharacter);return `${characterImage(c.id)}<div><small>BELLA CREW / NHÂN VẬT CỦA BẠN</small><strong>${c.name}</strong><span>${c.tag}</span></div><button type="button" data-character-picker>Chọn nhân vật ↗</button>`;}
function openCharacterPicker(){
 if(!account)return;const inRoom=page==='room'&&room&&session;let draft=selectedCharacter;const modal=$('#modal');modal.classList.add('character-modal');
 const draw=()=>{const c=characterById(draft),owned=!isCharacterLocked(draft);modal.innerHTML=`<div class="character-dialog-head"><div><div class="eyebrow">BELLA SKIN SHOP · 🪙 ${number(account.coins)} COIN</div><h2>Chọn nhân vật của bạn.</h2></div><button type="button" data-character-close aria-label="Đóng chọn nhân vật">×</button></div><div class="character-preview" style="--character-color:${c.color}">${c.locked?`<button type="button" class="character-animate" data-preview-blink aria-label="Xem hoạt ảnh nhân vật">${characterImage(c.id,'character-full')}</button>`:characterImage(c.id,'character-full')}<div><small>${c.price===0?'SKIN MIỄN PHÍ':c.locked?'SKIN HIỆU ỨNG':'SKIN THƯỜNG'}</small><h3>${c.name}</h3><p>${c.tag}</p><span>${owned?'Đã sở hữu':number(c.price)+' coin'}</span></div></div><div class="character-grid" role="group" aria-label="Bộ sưu tập nhân vật Bella">${[...CHARACTERS].sort((a,b)=>(a.price===0?-1:b.price===0?1:0)).map(c=>`<button type="button" class="character-option ${draft===c.id?'selected':''} ${isCharacterLocked(c.id)?'locked':''}" data-character="${c.id}" aria-pressed="${draft===c.id}" style="--character-color:${c.color}">${characterImage(c.id)}<strong>${c.name}</strong><span>${isCharacterLocked(c.id)?'🪙 '+c.price+' coin':c.price===0?'Miễn phí':'✓ Đã sở hữu'}</span></button>`).join('')}</div><p class="character-note">Skin chỉ thay đổi diện mạo. Coin và bộ sưu tập được lưu theo tài khoản.</p><button type="button" class="primary character-save">${owned?'Dùng nhân vật này →':'Đổi skin · '+c.price+' coin'}</button>`;
 modal.querySelector('[data-character-close]').onclick=()=>modal.close();modal.querySelector('[data-preview-blink]')?.addEventListener('click',e=>{const eyes=e.currentTarget.querySelector('.bella-eyelids');if(eyes)eyes.animate([{opacity:0},{opacity:1,offset:.2},{opacity:1,offset:.75},{opacity:0}],{duration:700});else e.currentTarget.querySelector('.hero-effects')?.animate([{opacity:.35},{opacity:1},{opacity:.8}],{duration:600});});
 modal.querySelectorAll('[data-character]').forEach(b=>b.onclick=()=>{draft=b.dataset.character;draw();modal.querySelector('[data-character="'+draft+'"]').focus();});
 modal.querySelector('.character-save').onclick=async()=>{if(isCharacterLocked(draft)){
  const panel=document.createElement('section');panel.className='unlock-popup';panel.setAttribute('role','alertdialog');panel.innerHTML='<div><h3>Đổi skin '+esc(c.name)+'</h3><p>Giá: <strong>'+c.price+' coin</strong><br>Số dư: '+number(account.coins)+' coin</p><button type="button" data-buy-cancel>Để sau</button><button type="button" class="primary" data-buy-confirm '+(account.coins<c.price?'disabled':'')+'>'+(account.coins<c.price?'Chưa đủ coin':'Xác nhận đổi skin')+'</button></div>';modal.append(panel);panel.querySelector('[data-buy-cancel]').onclick=()=>panel.remove();panel.querySelector('[data-buy-confirm]').onclick=async()=>{const b=panel.querySelector('[data-buy-confirm]');b.disabled=true;try{const data=await request({op:'buySkin',character:draft},null,null);applyAccount(data.account);draw();render();toast('Đã sở hữu '+c.name+'!');}catch(e){toast(e.message);b.disabled=false;}};return;
 }const button=modal.querySelector('.character-save');button.disabled=true;try{const data=await request({op:'equipSkin',character:draft},null,null);applyAccount(data.account);if(inRoom)accept(await request({op:'character',character:draft,code:session.code}));modal.close();render();toast('Đã chọn '+c.name);}catch(e){toast(e.message);button.disabled=false;}};
 };draw();modal.onclose=()=>modal.classList.remove('character-modal');modal.showModal();
}
function authScreen(){return `<main class="auth-shell"><div class="auth-brand"><img src="/assets/bella.png" alt="Bella"><span>BELLA POKER<small>PRIVATE TOURNAMENT CLUB</small></span></div><section class="auth-card"><div class="eyebrow">CHƠI CÙNG BẠN BÈ</div><h1>${authMode==='register'?'Tạo tài khoản':'Chào mừng trở lại.'}</h1><p>${authMode==='register'?'Chỉ cần tên đăng nhập và mật khẩu.':'Đăng nhập để giữ coin và bộ sưu tập skin của bạn.'}</p><div class="auth-tabs"><button data-auth-mode="login" class="${authMode==='login'?'active':''}">Đăng nhập</button><button data-auth-mode="register" class="${authMode==='register'?'active':''}">Đăng ký</button></div><form id="auth-form"><label>Tên đăng nhập<input name="username" required maxlength="32" autocomplete="username" placeholder="Tên đăng nhập"></label><label>Mật khẩu<input name="password" required type="password" maxlength="256" autocomplete="${authMode==='register'?'new-password':'current-password'}" placeholder="Mật khẩu"></label><button class="primary" ${authBusy?'disabled':''}>${authBusy?'Đang xử lý…':authMode==='register'?'Tạo tài khoản':'Đăng nhập'}</button><p id="auth-error" role="alert"></p></form><div class="auth-starter">${characterImage(DEFAULT_CHARACTER)}<div><strong>Bella nông dân miễn phí</strong><span>Skin khởi đầu dành cho mọi tài khoản.</span></div></div><small class="auth-rewards">Thắng tour có bot: +1 coin · Đăng nhập lại: hộp quà 1–5 coin</small></section></main>`;}
function accountToolbar(){return `<section class="account-toolbar"><div>${characterImage(selectedCharacter)}<span>${esc(account.username)}<small>TÀI KHOẢN BELLA</small></span></div><strong>🪙 ${number(account.coins)} <small>coin</small></strong><button data-shop>Đổi skin</button><button data-card-skins>Skin bài ♠</button><button data-logout aria-label="Đăng xuất">↗</button></section>`;}
function showLoginGift(amount){const modal=$('#modal');modal.classList.remove('character-modal');modal.classList.add('gift-modal');modal.innerHTML='<div class="gift-icon">🎁</div><div class="eyebrow">QUÀ ĐĂNG NHẬP</div><h2>Bạn nhận được</h2><strong class="gift-amount">+'+amount+' coin</strong><p>Coin đã được cộng vào ví của bạn.</p><button class="primary" data-close-gift>Tuyệt vời!</button>';modal.querySelector('[data-close-gift]').onclick=()=>modal.close();modal.onclose=()=>modal.classList.remove('gift-modal');modal.showModal();}
async function submitAuth(form){if(authBusy)return;authBusy=true;const b=form.querySelector('button.primary');b.disabled=true;try{const fields=Object.fromEntries(new FormData(form)),data=await request({op:authMode,...fields},null,null);applyAccount(data.account);authReady=true;render();if(data.gift)showLoginGift(data.gift);if(urlCode&&sessions[urlCode])await resume(urlCode);}catch(e){$('#auth-error').textContent=e.message;b.disabled=false;}finally{authBusy=false;}}
async function logoutAccount(){try{await request({op:'logout'},null,null);$('#modal').close();accountGeneration++;authMode='login';account=null;if(document.documentElement)document.documentElement.dataset.cardSkin='classic';session=null;room=null;sessions={};unlockedCharacters=[];selectedCharacter=DEFAULT_CHARACTER;page='home';render();}catch(e){toast(e.message);}}



function queueTableEffects(before,after){
 if(before?.code!==after.code)tableEffects.clear();
 if(before?.hand?.id!==after.hand?.id)for(const [key,e] of tableEffects)if(e.type!=='elimination')tableEffects.delete(key);
 for(const event of diffTableEffects(before,after)){if(tableEffects.has(event.key))continue;const effect={...event,started:Date.now()};tableEffects.set(event.key,effect);setTimeout(()=>{if(tableEffects.get(event.key)!==effect)return;tableEffects.delete(event.key);if(event.type==='blind'){render();return;}document.querySelectorAll('[data-effect-key]').forEach(el=>{if(el.dataset.effectKey===event.key&&event.type!=='board'&&event.type!=='hole')el.remove();});},event.duration+50);}
}
function chipDeduction(playerId){const effects=[...tableEffects.values()].filter(e=>e.type==='chips'&&e.playerId===playerId&&Date.now()-e.started<e.duration);return effects.map(e=>`<span class="chip-delta" data-effect-key="${esc(e.key)}" aria-label="Trừ ${number(e.amount)} chip">−${number(e.amount)}<small>chip</small></span>`).join('');}

function watchStatus(){const watchers=room.players.filter(p=>p.watchingId);return watchers.length?'<div class="watch-status" aria-live="polite">👁 '+watchers.map(p=>esc(p.name)+' → '+esc(room.players.find(x=>x.id===p.watchingId)?.name)).join(' · ')+'</div>':'';}
function tableExtraControls(me){return (me.rank>1&&room.status==='running'?'<label class="watch-picker">Xem bài <select data-watch aria-label="Chọn người để xem bài"><option value="">Chọn người chơi…</option>'+room.players.filter(p=>!p.rank&&p.id!==me.id).map(p=>'<option value="'+p.id+'" '+(me.watchingId===p.id?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label>':'')+(room.hand.stage==='complete'&&me.folded&&me.inHand?'<button class="show-folded" data-show-folded '+(room.hand.shownCards?.includes(me.id)||busy?'disabled':'')+'>'+(room.hand.shownCards?.includes(me.id)?'✓ Đã khoe bài':'Khoe 2 lá bài của tôi')+'</button>':'');}
function holeCard(c,index,ownerId){const front=card(c,false,false,!!winningCards?.players[ownerId]?.includes(index),!!winningCards&&!winningCards.players[ownerId]?.includes(index));const e=[...tableEffects.values()].find(e=>e.type==='hole'&&e.index===index&&e.playerId===ownerId);return '<div class="hole-slot"'+(room.hand.stage==='complete'?' data-card-skin="'+esc(room.players.find(p=>p.id===ownerId)?.cardSkin||'classic')+'"':'')+'><div class="hole-flipper" '+(e?'data-effect-key="'+esc(e.key)+'"':'')+'><div class="hole-front">'+front+'</div><div class="hole-back" aria-hidden="true">'+card(null,true)+'</div></div></div>';}

function boardCard(c,index){if(!c)return `<div class="board-slot">${card(null,false,true)}</div>`;const e=[...tableEffects.values()].find(e=>e.type==='board'&&e.index===index);return `<div class="board-slot"><div class="board-flipper" ${e?'data-effect-key="'+esc(e.key)+'"':''}><div class="board-card-front">${card(c,false,false,!!winningCards?.board.includes(index),!!winningCards&&!winningCards.board.includes(index))}</div><div class="board-card-back" aria-hidden="true">${card(null,true)}</div></div></div>`;}
function blindNotice(){const e=[...tableEffects.values()].find(e=>e.type==='blind'&&Date.now()-e.started<e.duration);if(!e)return '';return `<div class="game-hint blind-notice" data-effect-key="${esc(e.key)}" role="status" aria-live="polite"><span class="hint-symbol">↑</span><div><strong>Blind tăng</strong><span>${number(e.from.sb)}/${number(e.from.bb)} → ${number(e.to.sb)}/${number(e.to.bb)}</span></div><small id="turn-clock"></small></div>`;}
function eliminationNotice(){return [...tableEffects.values()].filter(e=>e.type==='elimination'&&Date.now()-e.started<e.duration).map(e=>`<aside class="elimination-banner" data-effect-key="${esc(e.key)}" role="status" aria-live="polite"><span class="elimination-icon">♠</span><div><small>NGƯỜI CHƠI BỊ LOẠI</small>${e.players.map(p=>`<strong>${esc(p.name)}${p.id===room.me?' · Bạn':''} <span>— Hạng #${p.rank}</span></strong>`).join('')}<p>Đã kết thúc lượt thi đấu trong giải.</p></div><button data-dismiss-elimination="${esc(e.key)}" aria-label="Đóng thông báo loại">×</button></aside>`).join('');}
function playTableEffects(){
 if(!tableEffects.size)return;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 document.querySelectorAll('[data-effect-key]').forEach(el=>{const e=tableEffects.get(el.dataset.effectKey);if(!e)return;const elapsed=Date.now()-e.started;if(elapsed>=e.duration||reduced)return;
 let frames=(e.type==='board'||e.type==='hole')?[{transform:'rotateY(180deg)'},{transform:'rotateY(0deg)'}]:e.type==='chips'?[{opacity:0,transform:'translate(-50%,5px) scale(.8)',offset:0},{opacity:1,transform:'translate(-50%,-5px) scale(1.08)',offset:.18},{opacity:1,transform:'translate(-50%,-17px) scale(1)',offset:.65},{opacity:0,transform:'translate(-50%,-32px) scale(.95)',offset:1}]:[{opacity:0,transform:'translateY(-12px)',offset:0},{opacity:1,transform:'translateY(0)',offset:.06},{opacity:1,transform:'translateY(0)',offset:.93},{opacity:0,transform:'translateY(-8px)',offset:1}];
 const animation=el.animate(frames,{duration:e.duration-e.delay,delay:e.delay,easing:(e.type==='board'||e.type==='hole')?'cubic-bezier(.2,.6,.2,1)':'ease-out',fill:'both'});animation.currentTime=elapsed;
 });
}


function syncEquity(){
 const input=page==='room'?equityInputs(room):null,key=input?JSON.stringify({hand:room.hand.id,...input}):null;if(key===equityKey)return;equityKey=key;equityResult=null;if(!input)return;
 if(equityBroken){equityResult={error:true};return;}
 try{if(!equityWorker){equityWorker=new Worker('/equity-worker.js',{type:'module'});equityWorker.onmessage=({data})=>{if(data.key!==equityKey)return;equityResult=data;updateEquityPanel();};equityWorker.onerror=()=>{equityBroken=true;equityResult={error:true};updateEquityPanel();};}equityWorker.postMessage({key,input});}catch{equityBroken=true;equityResult={error:true};}
}
function equityContent(){
 const me=room?.players.find(p=>p.id===room.me),won=winningSelection(room);let text='Chờ chia bài',value=null;
 if(won){text=(won.shared?'Chia pot':'Thắng')+' · '+won.name;}
 else if(room?.hand?.stage==='complete')text='Ván đã kết thúc';
 else if(me?.folded)text='Đã bỏ bài';
 else if(equityKey)text=equityResult?.error?'Chưa có ước tính':equityResult?'≈ '+Math.round(equityResult.equity)+'%':'Đang tính…';
 if(equityKey&&equityResult&&!equityResult.error)value=Math.max(0,Math.min(100,equityResult.equity));
 return `<div class="equity-caption"><span>${room?.hand?.stage==='complete'?'KẾT QUẢ':'ƯỚC TÍNH THẮNG'}</span><output>${esc(text)}</output></div><div class="equity-track" ${value===null?'aria-hidden="true"':`role="meter" aria-label="Tỉ lệ thắng ước tính" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(value)}"`}><i style="width:${value??0}%"></i></div>`;
}
function equityPanel(){return '<div id="equity-panel" class="equity-panel" title="Ước tính từ bài bạn và bài chung đã mở, so với bài đối thủ ngẫu nhiên. Tính hòa chia pot; chưa xét side pot.">'+equityContent()+'</div>';}
function updateEquityPanel(){const el=$('#equity-panel');if(el)el.innerHTML=equityContent();}

function header(){return `<header class="header"><div class="brand"><img src="/assets/bella.png" alt="Bella Team"><div>BELLA POKER<small>PRIVATE TOURNAMENT CLUB</small></div></div><nav aria-label="Điều hướng"><button data-nav="home" class="${page==='home'?'current':''}">Phòng thi đấu</button><button data-nav="ranking" class="${page==='ranking'?'current':''}">Bảng xếp hạng</button></nav><div class="status"><i class="dot"></i><span>${online?'Đã kết nối':'Đang kết nối lại'}</span></div></header>`;}
const storageNotice=()=>storage==='local'?'<div class="local-banner">Đang chạy máy chủ cục bộ. Các thiết bị phải kết nối cùng máy chủ này; bản Vercel cần cấu hình kho dữ liệu online.</div>':storage==='unconfigured'?'<div class="error-banner">Máy chủ chưa được cấu hình kho dữ liệu online. Chưa thể tạo hoặc tham gia giải.</div>':'';
function home(){return `<main class="shell">${storageNotice()}<section class="hero"><div><div class="eyebrow">Your friends. Your final table.</div><h1>Một phòng riêng.<br>Một <em>nhà vô địch.</em></h1><p class="subtle">Tạo giải poker của bạn, gửi lời mời đến hội bạn.<br>Cùng bắt đầu. Đấu đến người cuối cùng.</p><div class="badges"><span>Texas Hold’em</span><span>Tournament freezeout</span><span>2–9 người · Có bot luyện tập</span></div></div><div class="hero-art" role="img" aria-label="Không gian bàn poker Bella"><div class="tag"><i class="dot"></i> &nbsp; PRIVATE TOURNAMENTS ONLY</div><img src="/assets/bella.png" alt="Bella mascot"></div></section><section class="character-summary" data-character-summary>${characterSummary()}</section><div class="section-title"><h2>Vào cuộc theo cách của bạn</h2><button class="ghost small" data-rules>Luật thi đấu ↗</button></div><div class="cards"><form class="panel" id="create"><div class="eyebrow">01 / Host a tournament</div><h2 style="margin-top:12px">Tạo phòng thi đấu</h2><div class="subtle">Bạn là chủ phòng. Mọi người cùng một stack khởi đầu.</div><div class="form-grid"><label>TÊN CỦA BẠN<input name="name" minlength="2" maxlength="22" required value="${esc(profile)}" readonly></label><label>TÊN GIẢI<input name="title" maxlength="48" value="Bella Home Tournament" required></label><label>STACK KHỞI ĐẦU<select name="startingStack"><option value="1500">1.500 chip</option><option value="3000">3.000 chip</option><option value="5000" selected>5.000 chip</option><option value="10000">10.000 chip</option></select></label><label>THỜI GIAN MỖI LEVEL<select name="levelMinutes"><option value="3">3 phút · Turbo</option><option value="5" selected>5 phút · Tiêu chuẩn</option><option value="10">10 phút · Deep</option></select></label><label class="peek-option"><input type="checkbox" name="peek" checked><span><b>Nặn bài đầu ván</b><small>Mỗi ván mới có 5–10 giây kéo tấm che xem bài và thả cảm xúc. Turbo 5 giây, Tiêu chuẩn 8 giây, Deep 10 giây.</small></span></label></div><div class="form-actions"><small>Chỉ chip thi đấu.<br>Không nạp/rút, không mua lại chip.</small><div class="create-buttons"><button type="submit" name="mode" value="bot" ${busy||storage==='unconfigured'?'disabled':''}>🤖 Chơi với bot</button><button class="primary" ${busy||storage==='unconfigured'?'disabled':''}>${busy?'Đang tạo…':'Tạo phòng →'}</button></div></div></form><form class="panel join-box" id="join"><div class="eyebrow">02 / Join your friends</div><h2 style="margin-top:12px">Đã có lời mời?</h2><div class="subtle">Nhập mã 6 ký tự từ chủ phòng để giữ chỗ cho bạn.</div><div class="form-grid"><label>TÊN CỦA BẠN<input name="name" minlength="2" maxlength="22" required value="${esc(profile)}" readonly></label><label>MÃ PHÒNG<input class="code-input" name="code" minlength="6" maxlength="6" pattern="[A-Za-z2-9]{6}" required value="${esc(urlCode)}" placeholder="ABC234" autocomplete="off"></label></div><div class="form-actions"><small>Đăng ký đóng khi giải bắt đầu.<br>Hãy vào phòng trước giờ chia bài.</small><button class="primary" ${busy||storage==='unconfigured'?'disabled':''}>Tham gia →</button></div>${Object.keys(sessions).length?`<div class="recent"><span>Đã có ghế trong một giải?</span><button type="button" class="small" data-resume="${esc(Object.keys(sessions).at(-1))}">Quay lại bàn</button></div>`:''}</form></div><div class="steps"><div class="step"><b>01</b><div><strong>Tập hợp hội bạn</strong><br>Chia sẻ mã hoặc link phòng riêng.</div></div><div class="step"><b>02</b><div><strong>Chơi một giải trọn vẹn</strong><br>Blinds tăng. Hết chip là kết thúc lượt thi đấu.</div></div><div class="step"><b>03</b><div><strong>Theo dõi vị trí của bạn</strong><br>Bảng xếp hạng cập nhật suốt giải.</div></div></div><footer class="footnote"><span>BELLA TEAM · PLAY TOGETHER, FINISH STRONG.</span><span>Không cash game · Không tiền thật · Không rebuy / re-entry</span></footer></main>`;}
function stats(){const c=room.config;return `<div class="config-strip"><div class="stat"><span>STACK KHỞI ĐẦU</span><strong>${number(c.startingStack)}</strong></div><div class="stat"><span>LEVEL / BLINDS ĐẦU</span><strong>${c.levelMinutes} phút · 25 / 50</strong></div><div class="stat"><span>NGƯỜI CHƠI</span><strong>${room.players.length} người</strong></div><div class="stat"><span>THỂ THỨC</span><strong>Freezeout · ${c.peek?'Nặn bài '+c.peekSeconds+'s':'Không nặn bài'}</strong></div></div>`;}
function roomHeading(){return `<div class="room-heading"><button class="ghost small" data-nav="home">‹ Sảnh</button><div><div class="eyebrow">PRIVATE TOURNAMENT</div><h1>${esc(room.title)}</h1><span class="subtle">Mã phòng &nbsp; <b class="room-code">${esc(room.code)}</b></span></div><div class="right"><button class="small" data-copy="code">Sao chép mã</button><button class="primary small" data-copy="link">Mời bạn bè ↗</button></div></div>`;}
function waiting(){const me=room.players.find(p=>p.id===room.me),allReady=room.players.length>=2&&room.players.every(p=>p.ready),host=room.ownerId===room.me;return `<main class="shell">${storageNotice()}${roomHeading()}${stats()}<div class="waiting-character"><button class="small" data-character-picker>Đổi nhân vật của bạn ↗</button></div><div class="section-title"><h2>Gặp nhau ở bàn đấu</h2><span class="subtle">${room.players.filter(p=>p.ready).length} người đã sẵn sàng</span>${host?`<button class="small" data-add-bot ${busy||room.players.length>=9?'disabled':''}>＋ Thêm bot</button>`:''}</div><section class="players-grid">${room.players.map(p=>`<div class="player-slot"><div class="avatar mascot-avatar">${characterImage(p.character)}</div><div><b>${esc(p.name)} ${p.id===room.me?'· Bạn':''}</b><div class="subtle">${p.isBot?'BOT · Tự động chơi':p.id===room.ownerId?'Chủ phòng':'Người chơi'} · Ghế ngẫu nhiên khi bắt đầu</div><div class="${p.ready?'ready':'subtle'}">${p.ready?'✓ Sẵn sàng':'Đang chuẩn bị…'}</div></div>${host&&p.isBot?`<button class="bot-remove ghost small" data-remove-bot="${p.id}" aria-label="Xóa ${esc(p.name)}" ${busy?'disabled':''}>Xóa</button>`:''}</div>`).join('')}${room.players.length<9?'<div class="player-slot empty">＋ &nbsp; Mời thêm bạn vào phòng</div>':''}</section><div class="waiting-bottom"><div class="subtle">${host?'Số người được tính tự động. Bắt đầu khi cả phòng đã sẵn sàng.':'Chủ phòng sẽ bắt đầu khi mọi người đã sẵn sàng.'}<br><small>Hãy giữ trang mở để nhận lượt chơi.</small></div><div class="buttons"><button data-ready class="${me.ready?'active':'primary'}" ${busy?'disabled':''}>${me.ready?'✓ Đã sẵn sàng':'Tôi sẵn sàng'}</button>${host?`<button class="primary" data-start ${!allReady||busy?'disabled':''}>Bắt đầu giải →</button>`:''}</div></div></main>`;}
const suits={c:'♣',d:'♦',h:'♥',s:'♠'},ranks={11:'J',12:'Q',13:'K',14:'A'};
function card(c,back=false,empty=false,winning=false,losing=false){return `<div class="card ${winning?'winning-card':losing?'losing-card':''} ${back?'back':empty?'empty':c&&['h','d'].includes(c.suit)?'red':''}" ${empty?'aria-hidden="true"':`aria-label="${back?'Bài úp':`${ranks[c?.rank]||c?.rank} ${suits[c?.suit]}`}"`}>${!back&&!empty?`${ranks[c.rank]||c.rank}<span>${suits[c.suit]}</span>`:''}</div>`;}
function rankList(){return `<div class="rank-list">${room.leaderboard.map(p=>`<div class="rank-row ${p.id===room.me?'own':''}"><span class="position">${p.position}</span>${characterImage(p.character)}<div class="details"><strong>${esc(p.name)}${p.isBot?' · BOT':''}${p.id===room.me?' · Bạn':''}</strong><small>${p.rank?(p.rank===1?'Nhà vô địch':'Đã kết thúc giải'):'Đang thi đấu'}</small></div><span class="chips">${number(p.stack)}</span></div>`).join('')}</div>`;}
function ranksPanel(){return `<aside class="sidebar"><header><h3>Bảng xếp hạng</h3><small>${room.status==='finished'?'Kết quả chính thức':'Giải hiện tại · theo chip'}</small></header>${rankList()}<div class="rank-note">${room.status==='finished'?'Thứ hạng được chốt khi giải kết thúc.':'Thứ hạng còn thay đổi. Người hết chip nhận thứ hạng kết thúc; chip cược đang nằm trong pot.'}</div><div class="log" aria-label="Nhật ký ván">${room.hand?.log.slice(-6).map(s=>`<div>${esc(s)}</div>`).join('')||'Chưa có hành động.'}</div></aside>`;}
function raiseBounds(){const legal=room.legal;return {min:Math.min(legal.minRaiseTo,legal.maxRaiseTo),max:legal.maxRaiseTo};}
function raiseKey(){const h=room.hand,l=room.legal;return [h.id,h.stage,h.turn,h.currentBet,l.minRaiseTo,l.maxRaiseTo,l.canRaise].join(':');}
function selectedRaise(){const {min,max}=raiseBounds(),key=raiseKey();if(raiseDraft.key!==key)raiseDraft={key,value:min};raiseDraft.value=Math.max(min,Math.min(max,raiseDraft.value));return raiseDraft.value;}
function raiseOptions(){const {min,max}=raiseBounds(),h=room.hand,l=room.legal;return {min,max,sb:h.blinds.sb,bb:h.blinds.bb,pot:h.pot||0,currentBet:h.currentBet||0,toCall:l.callCost??l.toCall??0};}
function bbText(value,bb){return bb>0?`${Number((value/bb).toFixed(1)).toLocaleString('vi-VN')} BB`:'';}
function raiseDisplay(value){return `${number(value)}<small>${bbText(value,room.hand.blinds.bb)}</small>`;}
function raiseControls(){const {min,max}=raiseBounds(),value=selectedRaise(),disabled=!room.legal.canRaise||busy,opts=raiseOptions(),ladder=raiseLadder(opts),index=nearestStop(ladder,value);return `<div class="raise-controls"><div class="raise-heading"><label for="raise-slider">TĂNG CƯỢC ĐẾN</label><div class="raise-stepper"><button type="button" class="raise-step" data-raise-step="-1" aria-label="Giảm một mốc" ${disabled?'disabled':''}>−</button><output id="raise-display" aria-live="polite">${raiseDisplay(value)}</output><button type="button" class="raise-step" data-raise-step="1" aria-label="Tăng một mốc" ${disabled?'disabled':''}>+</button></div></div><div class="raise-presets" role="group" aria-label="Chọn nhanh mức cược">${raisePresets(opts).map(p=>`<button type="button" class="raise-preset ${p.value===value?'active':''}" data-raise-preset="${p.value}" ${disabled?'disabled':''}>${p.label}</button>`).join('')}</div><input id="raise-slider" class="raise-slider" aria-label="Kéo thanh để chọn mức cược theo nấc tròn" type="range" min="0" max="${Math.max(0,ladder.length-1)}" step="1" value="${index}" ${disabled||ladder.length<2?'disabled':''}><div class="raise-limits"><span>Tối thiểu ${number(min)}</span><span>All-in ${number(max)}</span></div>${!room.legal.canRaise?'<small class="subtle">Lượt này chưa được phép tăng cược.</small>':''}</div>`;}
function syncRaise(value){const {min,max}=raiseBounds();const next=Math.max(min,Math.min(max,Math.trunc(Number(value)||min)));raiseDraft={key:raiseKey(),value:next};const slider=$('#raise-slider');if(slider){const ladder=raiseLadder(raiseOptions()),index=nearestStop(ladder,next);slider.value=index;slider.style.setProperty('--raise-fill',(ladder.length<2?100:index/(ladder.length-1)*100)+'%');}const display=$('#raise-display');if(display)display.innerHTML=raiseDisplay(next);document.querySelectorAll('[data-raise-preset]').forEach(b=>b.classList.toggle('active',Number(b.dataset.raisePreset)===next));const button=$('[data-action="raise"]');if(button){button.disabled=busy||!room.legal.canRaise;button.textContent='Tăng đến '+number(next);}return next;}
function bindRaise(){const slider=$('#raise-slider');if(!slider)return;syncRaise(selectedRaise());slider.oninput=()=>{const ladder=raiseLadder(raiseOptions());syncRaise(ladder[Number(slider.value)]);};document.querySelectorAll('[data-raise-preset]').forEach(b=>b.onclick=()=>syncRaise(b.dataset.raisePreset));document.querySelectorAll('[data-raise-step]').forEach(b=>b.onclick=()=>{syncRaise(stepStop(raiseLadder(raiseOptions()),selectedRaise(),Number(b.dataset.raiseStep)));});}
function actionLabel(a){if(!a)return '';const label=a.kind==='raise'?'Raise đến '+number(a.total):a.kind==='call'?'Call '+number(a.paid):a.kind==='check'?'Check':'Fold';return (a.allIn?'All-in · ':'')+label;}
function opponentAction(p){const a=p.lastAction;if(!a)return '';return `<div class="opponent-action action-${a.kind}" aria-label="${esc(p.name)} · ${esc(actionLabel(a))}"><small>${esc(a.stage.toUpperCase())}</small><strong>${esc(actionLabel(a))}</strong></div>`;}
function latestAction(){const a=room.hand.lastAction;if(!a)return '<div class="table-last-action"><span>DIỄN BIẾN BÀN</span><strong>Chờ hành động đầu tiên…</strong></div>';const p=room.players.find(p=>p.id===a.playerId);return `<div class="table-last-action" aria-live="polite"><span>${esc(a.stage.toUpperCase())} · ${esc(p?.name||'Người chơi')}</span><strong>${esc(actionLabel(a))}</strong></div>`;}
function turnRing(id){if(room.hand?.turn!==id||room.hand.stage==='complete'||isPeeking())return '';return '<svg class="turn-ring" viewBox="0 0 100 40" preserveAspectRatio="none" aria-hidden="true"><rect class="turn-ring-track" x="2" y="2" width="96" height="36" rx="8" pathLength="100"/><rect class="turn-ring-progress" x="2" y="2" width="96" height="36" rx="8" pathLength="100"/></svg>';}
const serverNow=()=>Date.now()+clockOffset;
const isPeeking=()=>!!room?.hand?.peekUntil&&room.hand.stage!=='complete'&&serverNow()<room.hand.peekUntil;
const cardPeek=createCardPeek({soundUrl:'/assets/sfx/card-phach.wav',onReact:mood=>{if(!room?.hand)return;request({op:'react',mood,handId:room.hand.id,code:session.code}).then(accept).catch(e=>toast(e.message));}});
let peekTimers=[];
function syncPeek(){
 const h=room?.hand,me=room?.players.find(p=>p.id===room.me),active=page==='room'&&room?.status==='running'&&isPeeking()&&!!me?.inHand&&!me.rank&&me.hole?.length===2;
 cardPeek.sync(active?{active,handId:h.id,cards:me.hole,cardSkin:account?.equippedCardSkin||'classic',until:h.peekUntil-clockOffset,seconds:room.config.peekSeconds||8,mood:h.moods?.[me.id]??null}:null);
 // Re-render when the peek ends (actions open up) and again when dropped moods fade from the seats.
 peekTimers.forEach(clearTimeout);peekTimers=[];if(!h?.peekUntil)return;
 for(const at of [h.peekUntil,h.peekUntil+MOOD_LINGER_MS]){const wait=at-serverNow();if(wait>0)peekTimers.push(setTimeout(()=>{render();syncPeek();},wait+60));}
}
function moodTag(p){const h=room.hand,m=h?.moods?.[p.id];if(m==null||!h.peekUntil||serverNow()>h.peekUntil+MOOD_LINGER_MS||!MOODS[m])return '';return `<span class="mood-badge" aria-hidden="true">${moodIcon(m)}</span><span class="mood-label" style="--mood-color:${MOODS[m].color}" aria-label="Cảm xúc: ${MOODS[m].label}">${MOODS[m].label}</span>`;}
function gameSeat(p,h){
 const role=p.id===h.bbId?'BB':p.id===h.sbId?'SB':p.seat===h.buttonSeat?'D':'';
 const cardsVisible=h.stage==='complete'&&p.hole;
 return `<article class="opponent ${p.progress>0?'rail-seat':''} ${p.x<28||p.x>72?'hud-edge':''} ${p.id===h.turn&&!isPeeking()?'is-turn':''} ${p.folded&&!cardsVisible?'has-folded':''} ${p.rank>1&&!p.inHand?'is-out':''}" style="--seat-x:${p.x}%;--seat-y:${p.y}%;--seat-rows:${p.rows};--seat-columns:${p.columns};--seat-progress:${p.progress};--sprite-x:${(p.portrait%4)*100/3}%;--sprite-y:${p.portrait<4?0:100}%" aria-label="${esc(p.name)} · ${number(p.stack)} chip">${characterImage(p.character,'opponent-portrait bella-opponent')}${moodTag(p)}${cardsVisible?`<div class="opponent-cards" ${h.stage==='complete'?`data-card-skin="${esc(p.cardSkin||'classic')}"`:''}>${p.hole.map((c,i)=>card(c,false,false,!!winningCards?.players[p.id]?.includes(i),!!winningCards&&!winningCards.players[p.id]?.includes(i))).join('')}</div>`:''}<div class="opponent-plaque">${turnRing(p.id)}${role?`<span class="position-badge role-${role.toLowerCase()}">${role}</span>`:''}<strong>${esc(p.name)}</strong><div class="seat-balances"><span class="opponent-stack">${number(p.stack)}</span>${p.bet&&h.stage!=='complete'?`<span class="table-wager" aria-label="Đã cược ${number(p.bet)} chip">↑ ${number(p.bet)}</span>`:''}</div>${p.folded?'<small class="seat-condition">Đã bỏ bài</small>':p.allin?'<small class="seat-condition">ALL-IN</small>':p.rank>1?`<small class="seat-condition">OUT #${p.rank}</small>`:''}${opponentAction(p)}${chipDeduction(p.id)}${p.isBot?'<i class="bot-label">BOT</i>':''}</div></article>`;
}
function gameOverlay(){
 if(gamePanel!=='ranking')return '';
 return `<div class="game-overlay"><section class="game-sheet" role="dialog" aria-modal="true" aria-label="Bảng xếp hạng"><header><div><span class="eyebrow">BELLA TOURNAMENT</span><h2>Bảng xếp hạng</h2></div><button class="glass-button" data-close-panel aria-label="Đóng bảng">×</button></header>${rankList()}<div class="rank-note">${room.status==='finished'?'Thứ hạng cuối cùng của giải.':'Xếp hạng theo số chip đang có.'}</div><div class="log">${room.hand.log.slice(-6).map(s=>`<div>${esc(s)}</div>`).join('')}</div></section></div>`;
}
function table(){
 winningCards=showdownHighlights(room);const h=room.hand,me=room.players.find(p=>p.id===room.me),viewed=me.rank>1?room.players.find(p=>p.id===me.watchingId):null,handOwner=viewed||me,mine=room.leaderboard.find(p=>p.id===room.me),winner=room.players.find(p=>p.rank===1),peeking=isPeeking(),acting=peeking?null:room.legal;
 if(!acting||raiseOpenKey!==raiseKey()){raiseOpen=false;raiseOpenKey=acting?raiseKey():null;}
 const result=h.winners.filter(w=>w.hand!=='Hoàn phần cược dư').map(w=>`${room.players.find(p=>p.id===w.id)?.name} +${number(w.amount)}`).join(' · ');
 const hint=peeking?'Mọi người đang nặn bài. Lượt cược bắt đầu khi hết giờ.':room.status==='finished'?`${winner?.name} vô địch · Bạn xếp #${mine.position}`:h.stage==='complete'?result:acting?(acting.canCheck?'Bạn có thể check hoặc tăng cược.':`Cần theo ${number(acting.toCall)} chip để tiếp tục.`):me.rank?`Bạn đã kết thúc ở vị trí #${me.rank}.`:`${room.players.find(p=>p.id===h.turn)?.name||'Đối thủ'} đang suy nghĩ…`;
 const role=me.id===h.bbId?'BB':me.id===h.sbId?'SB':me.seat===h.buttonSeat?'D':'';
 return `<main class="game-shell ${raiseOpen?'raising':''} ${room.players.length>5?'many-seats':''} ${room.players.length===2?'heads-up':''}" aria-label="Bàn poker góc nhìn người chơi"><div class="lounge-backdrop" aria-hidden="true"></div><div class="game-topbar"><button class="glass-button exit-button" data-nav="home" aria-label="Về sảnh">×</button><div class="game-brand"><img src="/assets/bella.png" alt="Bella"><span>BELLA<span>PRIVATE CLUB</span></span></div><div class="game-top-actions"><button class="glass-button" data-rules aria-label="Luật thi đấu">⚑</button><button class="glass-button board-count" data-copy="link" aria-label="Chia sẻ phòng"><span>▱</span> ${h.board.length}/5</button></div></div><div class="game-room-info"><span>${esc(room.title)}</span><small>${room.code} · Ván ${h.number} · ${number(h.blinds.sb)}/${number(h.blinds.bb)}</small></div><aside class="game-chip-card" aria-label="Chip của bạn"><span>CHIP CỦA BẠN</span><strong>${number(me.stack)}</strong><small>Đã cược vòng này: ${number(me.bet)}</small>${equityPanel()}${chipDeduction(me.id)}</aside><div class="game-pot"><span>${h.stage==='complete'?'KẾT QUẢ':'TỔNG POT'}</span><strong>${number(displayedPot(room))}</strong></div><svg class="perspective-table" viewBox="0 0 480 1000" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="rail" x1="0" x2="1"><stop stop-color="#af7a42"/><stop offset=".13" stop-color="#efd3a3"/><stop offset=".5" stop-color="#c39a67"/><stop offset=".84" stop-color="#f8dfac"/><stop offset="1" stop-color="#8b5e34"/></linearGradient><radialGradient id="felt" cx=".48" cy=".28" r=".8"><stop stop-color="#28615e"/><stop offset="1" stop-color="#103c3c"/></radialGradient><pattern id="felt-fibre" width="4" height="4" patternUnits="userSpaceOnUse"><path d="M0 1H4M1 0V4" stroke="#e8fff8" stroke-opacity=".035" stroke-width=".5"/></pattern></defs><path class="table-shadow" d="M73 1020Q28 974 44 859L105 470C117 350 363 350 375 470L436 859Q452 974 407 1020Z"/><path d="M73 1020Q28 974 44 859L105 470C117 350 363 350 375 470L436 859Q452 974 407 1020Z" fill="url(#rail)" stroke="#e8c795" stroke-width="2"/><path d="M91 1020Q47 970 63 860L121 473C132 378 348 378 359 473L417 860Q433 970 389 1020Z" fill="url(#felt)" stroke="#152f2f" stroke-width="6"/><path d="M91 1020Q47 970 63 860L121 473C132 378 348 378 359 473L417 860Q433 970 389 1020Z" fill="url(#felt-fibre)"/><path d="M98 1015Q57 967 72 860L130 474C140 390 340 390 350 474L408 860Q423 967 382 1015" fill="none" stroke="#d3c095" stroke-opacity=".75" stroke-width="1.5"/></svg><div class="table-branding">♠ BELLA TOURNAMENT</div>${portraitSeats(room.players,me).map(p=>gameSeat(p,h)).join('')}<div class="game-board" ${h.stage==='complete'?`data-card-skin="${esc(room.players.find(p=>h.winners.some(w=>w.id===p.id&&w.amount>0&&w.hand!=='Hoàn phần cược dư'))?.cardSkin||'classic')}"`:''}><div class="board">${Array.from({length:5},(_,i)=>boardCard(h.board[i],i)).join('')}</div></div><div class="hero-hand">${viewed?`<span class="viewing-label">👁 Đang xem ${esc(viewed.name)}</span>`:''}${handOwner.hole&&handOwner.inHand?`<button id="peek" aria-label="Giữ để nâng bài"><div class="holecards ${peek?'peeking':''}">${handOwner.hole.map((c,i)=>holeCard(c,i,handOwner.id)).join('')}</div></button>`:''}<div class="hero-plaque ${h.turn===me.id&&!isPeeking()?'is-turn':''}">${turnRing(me.id)}${role?`<span class="position-badge role-${role.toLowerCase()}">${role}</span>`:''}<button class="hero-character" data-character-picker aria-label="Đổi nhân vật của bạn">${characterImage(me.character)}${moodTag(me)}</button><strong>${esc(me.name)} <span>· Bạn</span></strong><b>${number(me.stack)}</b></div></div><button class="game-rank-shortcut" data-game-ranking aria-label="Mở bảng xếp hạng">${characterImage(me.character)}<span>♛ #${mine.position}</span></button><div class="game-level"><span>LEVEL ${h.blinds.level}</span><strong id="level-clock">--:--</strong></div><section class="game-dock" aria-label="Thao tác chơi"><div class="dock-handle"></div>${blindNotice()||`<div class="game-hint"><span class="hint-symbol">✦</span><div><strong>${peeking?'Nặn bài':acting?'Đến lượt bạn':h.stage==='complete'?'Kết quả ván':'Bella Club'}</strong><span>${esc(hint)}</span></div><small id="turn-clock"></small></div>`}${watchStatus()}${acting&&raiseOpen?`<div class="raise-drawer">${raiseControls()}<div class="raise-confirm"><button data-action="allin" ${busy||(!acting.canRaise&&acting.maxRaiseTo>h.currentBet)?'disabled':''}>Tất tay</button><button class="primary" data-action="raise" ${!acting.canRaise||busy?'disabled':''}>Xác nhận tăng</button></div></div>`:''}<div class="game-actions">${acting?`<button data-action="fold" ${busy?'disabled':''}>Bỏ bài</button><button data-action="${acting.canCheck?'check':'call'}" ${busy?'disabled':''}>${acting.canCheck?'Check':'Theo '+number(acting.toCall)}</button><button data-raise-toggle aria-label="Tăng cược" aria-expanded="${raiseOpen}" ${!acting.canRaise||busy?'disabled':''}>Tăng <span>${raiseOpen?'⌄':'⌃'}</span></button>`:`<button class="idle-action" data-game-ranking>${room.status==='finished'?'♛ Xem thứ hạng':'♛ Bảng xếp hạng'}</button>${tableExtraControls(me)||'<button class="idle-action secondary" data-copy="link">Mời bạn ↗</button>'}`}</div><span class="dock-footnote">TOURNAMENT · ${room.players.filter(p=>!p.rank||p.rank===1).length}/${room.players.length} CÒN LẠI · ${online?'ĐÃ ĐỒNG BỘ':'ĐANG KẾT NỐI LẠI'}</span></section>${gameOverlay()}<div class="table-notices">${eliminationNotice()}</div></main>`;
}

function ranking(){return `<main class="shell"><div class="eyebrow">THE ROAD TO THE FINAL TABLE</div><div class="room-heading"><h1>Bảng xếp hạng giải</h1>${room?`<button class="primary small" data-room>Về ${room.status==='waiting'?'phòng chờ':'bàn chơi'} →</button>`:''}</div>${room?`<div class="subtle">${esc(room.title)} · ${room.code} · ${room.status==='finished'?'Đã kết thúc':'Đang diễn ra'}</div><section class="panel" style="margin-top:22px">${rankList()}</section><p class="subtle">Xếp hạng trực tiếp theo số chip còn lại. Khi bị loại, thứ hạng được chốt theo thứ tự loại. Các người chơi bị loại cùng ván, có stack đầu ván bằng nhau, nhận cùng thứ hạng.</p>`:`<div class="panel empty-state"><div class="eyebrow">MỖI GIẢI, MỘT CÂU CHUYỆN</div><h2>Vị trí đầu tiên đang chờ bạn.</h2><p>Tham gia một phòng tournament để xem<br>thứ hạng của mình và hội bạn theo thời gian thực.</p><button class="primary" data-nav="home">Tìm hội bạn →</button></div>`}</main>`;}

let seatResizeObserver=typeof ResizeObserver==='undefined'?null:new ResizeObserver(()=>positionTableSeats());
function positionTableSeats(){
 const stage=$('.game-shell');if(!stage)return;const opponents=stage.querySelectorAll('.opponent').length;if(!opponents)return;
 const cardWidth=Math.min(34,Math.max(23,stage.clientWidth*.08));stage.style.setProperty('--board-card-width',cardWidth+'px');stage.style.setProperty('--board-card-height',Math.round(cardWidth*1.44)+'px');
 const dock=stage.querySelector('.game-dock'),notice=stage.querySelector('.watch-status');stage.style.setProperty('--community-height',notice?notice.getBoundingClientRect().height+6+'px':'0px');
 const base=stage.getBoundingClientRect(),hud=[...stage.querySelectorAll('.game-pot,.game-chip-card')],board=stage.querySelector('.game-board .board'),hero=stage.querySelector('.hero-plaque');if(!board||!hero)return;
 const top=Math.max(...hud.map(el=>el.getBoundingClientRect().bottom))-base.top+12;
 const slots=[...board.querySelectorAll('.board-slot')].map(el=>el.getBoundingClientRect());
 const utilities=[...stage.querySelectorAll('.game-rank-shortcut,.game-level')].map(el=>el.getBoundingClientRect()).filter(r=>r.width>0);const bottom=Math.min(hero.getBoundingClientRect().bottom,...utilities.map(r=>r.top))-base.top-12;
 const metrics=seatMetrics({width:stage.clientWidth,top,bottom,boardTop:board.getBoundingClientRect().top-base.top,boardLeft:Math.min(...slots.map(r=>r.left))-base.left,boardRight:Math.max(...slots.map(r=>r.right))-base.left,opponents});
 for(const [name,value] of Object.entries({top:metrics.top,bottom:metrics.bottom,width:metrics.cellWidth,railWidth:metrics.railWidth,height:metrics.cellHeight,portrait:metrics.portrait}))stage.style.setProperty('--seat-'+name,value+'px');
}
function watchTableSeats(){seatResizeObserver?.disconnect();positionTableSeats();const stage=$('.game-shell');if(stage)seatResizeObserver?.observe(stage);}

function render(){syncEquity();document.body.classList.toggle('in-game',page==='room'&&!!room&&room.status!=='waiting');const focused=document.activeElement,focusId=focused?.id==='raise-slider'?focused.id:null,key=raiseDraft.key;app.innerHTML=!authReady?'<main class="auth-shell"><p>Đang kết nối Bella…</p></main>':!account?authScreen():header()+accountToolbar()+(page==='home'?home():page==='ranking'?ranking():room?.status==='waiting'?waiting():room?table():home());bind();watchTableSeats();playTableEffects();if(focusId&&key===raiseDraft.key&&$('#'+focusId)){$('#'+focusId).focus();}updateClocks();if(page!=='room')cardPeek.sync(null);}
function updateClocks(){if(!room)return;const now=Date.now()+clockOffset;const deadline=room.hand?.stage==='complete'?room.hand.nextHandAt:room.hand?.deadline;const seconds=Math.max(0,Math.ceil(((deadline||now)-now)/1000));const turnClock=$('#turn-clock');if(turnClock){const own=room.status==='running'&&room.hand?.stage!=='complete'&&room.hand?.turn===room.me;turnClock.classList.toggle('own-turn',own);turnClock.classList.toggle('turn-warning',own&&seconds<=10&&seconds>5);turnClock.classList.toggle('turn-urgent',own&&seconds<=5);const peekLeft=isPeeking()?Math.ceil((room.hand.peekUntil-now)/1000):0;turnClock.textContent=room.status==='finished'?'Kết thúc':peekLeft?`${peekLeft}s`:room.hand?.stage==='complete'?`Ván mới · ${seconds}s`:own?`${seconds}s`:`Còn ${seconds}s`;turnClock.setAttribute('aria-label',own?`Lượt của bạn còn ${seconds} giây`:turnClock.textContent);}const fraction=turnFraction(room,now);document.querySelectorAll('.turn-ring-progress').forEach(el=>el.style.strokeDashoffset=String(100*(1-fraction)));const remain=Math.max(0,Math.ceil((room.blinds.endsAt-now)/1000));if($('#level-clock'))$('#level-clock').textContent=room.status==='finished'?'Kết thúc':`${Math.floor(remain/60)}:${String(remain%60).padStart(2,'0')}`;if($('#connection-label'))$('#connection-label').textContent=online?'Đã đồng bộ':'Đang kết nối lại';}
async function entry(form,op,extra={}){if(busy)return;const body=Object.fromEntries(new FormData(form));profile=account.username;body.name=profile;localStorage.setItem('bella.profile',JSON.stringify(profile));busy=true;form.querySelector('button.primary').disabled=true;try{const data=await request({op,...body,character:selectedCharacter,...extra});page='room';accept(data);history.replaceState(null,'',`?room=${data.room.code}`);}catch(e){toast(e.message);}finally{busy=false;render();}}
async function resume(code){if(!sessions[code]){toast('Không tìm thấy phiên của bạn trên trình duyệt này.');return;}session=sessions[code];try{const data=await request(null);page='room';accept(data);history.replaceState(null,'',`?room=${code}`);}catch(e){session=null;toast(e.message);}}
function rules(){const modal=$('#modal');modal.innerHTML='<h2>Luật của bàn Bella</h2><p>No-limit Texas Hold’em · Tournament một bàn · 2–9 người.</p><ul><li>Mỗi người cùng stack khởi đầu. Không có nạp tiền, cash-out, rebuy hoặc re-entry.</li><li>Blinds bắt đầu 25/50 và tăng theo thời lượng chủ phòng chọn. Level mới áp dụng từ ván tiếp theo; bản này không ante.</li><li>Chủ phòng chỉ bắt đầu khi mọi người đã sẵn sàng. Không nhận người mới sau khi bắt đầu.</li><li>Chủ phòng có thể thêm hoặc xóa bot trong phòng chờ. Bot tự sẵn sàng, chơi theo cùng luật và chỉ biết bài riêng của mình cùng bài chung.</li><li>Mỗi lượt có 25 giây. Hết giờ tự check nếu được phép, nếu không tự bỏ bài. Mất kết nối vẫn giữ ghế và chịu blinds.</li><li>Tăng cược tối thiểu bằng mức tăng đầy đủ gần nhất. All-in thiếu mức tăng không tự mở lại quyền raise.</li><li>All-in nhiều mức được chia main pot và side pot riêng. Bài ngang nhau chia pot; chip lẻ theo vị trí bên trái button.</li><li>Hết chip là bị loại. Một người còn chip sẽ vô địch. Loại cùng ván so stack đầu ván; stack bằng nhau đồng hạng.</li><li>Trong ván, bài riêng hiển thị cho chủ bài và người đã bị loại đang công khai theo dõi họ. Khi so bài kết thúc, lật bài người còn đấu. Bài đã fold chỉ công khai khi chủ bài bấm Khoe bài sau khi kết thúc ván. Quay lại bằng cùng trình duyệt để giữ phiên.</li></ul><button class="primary" id="close-rules">Đã hiểu</button>';modal.showModal();$('#close-rules').onclick=()=>modal.close();}
function bind(){document.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>{authMode=b.dataset.authMode;render();});$('#auth-form')?.addEventListener('submit',e=>{e.preventDefault();submitAuth(e.currentTarget);});document.querySelectorAll('[data-shop]').forEach(b=>b.onclick=openCharacterPicker);document.querySelectorAll('[data-logout]').forEach(b=>b.onclick=logoutAccount);document.querySelector('[data-watch]')?.addEventListener('change',e=>send({op:'watch',playerId:e.target.value||null}));document.querySelector('[data-show-folded]')?.addEventListener('click',()=>send({op:'showCards',handId:room.hand.id}));document.querySelectorAll('[data-dismiss-elimination]').forEach(b=>b.onclick=()=>{tableEffects.delete(b.dataset.dismissElimination);b.closest('.elimination-banner').remove();});document.querySelectorAll('[data-character-picker]').forEach(b=>b.onclick=openCharacterPicker);document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;render();});document.querySelectorAll('[data-rules]').forEach(b=>b.onclick=rules);$('#create')?.addEventListener('submit',e=>{e.preventDefault();entry(e.currentTarget,'create',e.submitter?.value==='bot'?{withBot:true}:{});});$('#join')?.addEventListener('submit',e=>{e.preventDefault();entry(e.currentTarget,'join');});document.querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>resume(b.dataset.resume));document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{page='room';render();});document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const value=b.dataset.copy==='code'?room.code:`${location.origin}/?room=${room.code}`;try{await navigator.clipboard.writeText(value);toast(b.dataset.copy==='code'?'Đã sao chép mã phòng.':'Đã sao chép link mời.');}catch{toast(`Mã phòng: ${room.code}`);}});$('[data-ready]')?.addEventListener('click',()=>send({op:'ready',ready:!room.players.find(p=>p.id===room.me).ready}));$('[data-start]')?.addEventListener('click',()=>send({op:'start'}));$('[data-add-bot]')?.addEventListener('click',()=>send({op:'addBot'}));document.querySelectorAll('[data-remove-bot]').forEach(b=>b.onclick=()=>send({op:'removeBot',botId:b.dataset.removeBot}));bindRaise();document.querySelectorAll('[data-game-ranking]').forEach(b=>b.onclick=()=>{gamePanel='ranking';render();});$('[data-close-panel]')?.addEventListener('click',()=>{gamePanel=null;render();});$('[data-raise-toggle]')?.addEventListener('click',()=>{raiseOpen=!raiseOpen;render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{let amount;if(b.dataset.action==='raise'){amount=selectedRaise();const {min,max}=raiseBounds();if(!Number.isSafeInteger(amount)||amount<min||amount>max){toast('Chọn mức cược từ '+number(min)+' đến '+number(max)+' chip.');return;}}send({op:'action',kind:b.dataset.action,amount,handId:room.hand.id});});const peeker=$('#peek');if(peeker){
 const reveal=on=>{peek=on;$('.holecards')?.classList.toggle('peeking',on);};
 peeker.onpointerdown=e=>{e.preventDefault();peeker.setPointerCapture(e.pointerId);reveal(true);};peeker.onpointerup=()=>reveal(false);peeker.onpointercancel=()=>reveal(false);peeker.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();reveal(true);}};peeker.onkeyup=()=>reveal(false);
 }}
async function poll(){if(!account||!session||polling||page==='home'||document.hidden)return;polling=true;try{const data=await request(null);accept(data);}catch(e){online=false;updateClocks();if(Date.now()-lastErrorAt>20000){toast(e.message);lastErrorAt=Date.now();}}finally{polling=false;}}
render();request(null,'account',null).then(data=>{applyAccount(data.account);}).catch(()=>{account=null;}).finally(()=>{authReady=true;render();if(account&&urlCode&&sessions[urlCode])resume(urlCode);});request(null,'health',null).then(data=>{storage=data.storage;render();}).catch(()=>{online=false;storage='unknown';render();});
setInterval(poll,1500);setInterval(updateClocks,250);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});window.addEventListener('online',poll);

window.addEventListener('pointerup',()=>{if(peek){peek=false;render();}});
window.addEventListener('blur',()=>{if(peek){peek=false;render();}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&(gamePanel||raiseOpen)){gamePanel=null;raiseOpen=false;render();}});


configureCardSkins({getAccount:()=>account,request:async body=>{const data=await request(body,null,null);applyAccount(data.account);render();return data;}});
